  public int drawerGridsThresholdFile(int[][] drawers, int k) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {for(int[]row:a){int s=0;for(int x:row)s+=x;out.add(s);}}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
